import "dotenv/config";
import { defineConfig } from "prisma/config";

// Neon's pooled connection (PgBouncer, transaction mode) doesn't support the
// prepared statements / advisory locks Prisma Migrate needs, so migrations
// must run over the *unpooled* (direct) connection. DATABASE_URL_UNPOOLED
// falls back to DATABASE_URL for local Postgres, which has no pooler and
// only one URL to begin with.
export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: process.env["DATABASE_URL_UNPOOLED"] ?? process.env["DATABASE_URL"],
  },
});
